import { createContext } from "svelte";
import type { HTMLAttributes } from "svelte/elements";
import type { OTPValidationType } from "./otp-field-machine.js";

export interface OTPFieldContext {
  readonly activeIndex: number;
  readonly ariaDescribedBy: HTMLAttributes<HTMLDivElement>["aria-describedby"];
  readonly ariaInvalid: HTMLAttributes<HTMLDivElement>["aria-invalid"];
  readonly ariaLabel: HTMLAttributes<HTMLDivElement>["aria-label"];
  readonly ariaLabelledBy: HTMLAttributes<HTMLDivElement>["aria-labelledby"];
  readonly autocomplete: string | undefined;
  readonly disabled: boolean;
  readonly form: string | undefined;
  readonly inputMode: "decimal" | "email" | "none" | "numeric" | "search" | "tel" | "text" | "url";
  readonly length: number;
  readonly mask: boolean;
  readonly readonly: boolean;
  readonly required: boolean;
  readonly validationType: OTPValidationType;
  createSlot(): OTPFieldSlot;
  delete(slot: OTPFieldSlot, backward: boolean): void;
  focus(index: number): void;
  indexOf(slot: OTPFieldSlot): number;
  insert(raw: string, slot: OTPFieldSlot): void;
  register(slot: OTPFieldSlot, input: HTMLInputElement | null): void;
  unregister(slot: OTPFieldSlot): void;
  valueAt(slot: OTPFieldSlot): string;
}

export interface OTPFieldSlot {
  readonly key: symbol;
  element: HTMLInputElement | null;
}

export const [getOTPFieldContext, setOTPFieldContext] = createContext<OTPFieldContext>();

export type FieldRelationships = {
  describedBy: string | undefined;
  labelledBy: string | undefined;
};

function belongsToField(element: Element, field: Element): boolean {
  return element.closest('[data-slot="field"]') === field;
}

export function getFieldRelationships(element: Element): FieldRelationships | null {
  const field = element.closest('[data-slot="field"]');
  if (!field) return null;

  const label = Array.from(field.querySelectorAll<HTMLElement>('[data-slot="field-label"]')).find(
    (candidate) => belongsToField(candidate, field),
  );
  const messages = Array.from(
    field.querySelectorAll<HTMLElement>(
      '[data-slot="field-description"], [data-slot="field-error"]',
    ),
  ).filter((candidate) => belongsToField(candidate, field));

  return {
    describedBy:
      messages
        .map((message) => message.id)
        .filter(Boolean)
        .join(" ") || undefined,
    labelledBy: label?.id,
  };
}

export function observeFieldRelationships(element: Element, sync: () => void): () => void {
  const field = element.closest('[data-slot="field"]');
  if (!field) return () => undefined;

  const observer = new MutationObserver(sync);
  observer.observe(field, {
    attributeFilter: ["data-slot", "id"],
    attributes: true,
    childList: true,
    subtree: true,
  });
  queueMicrotask(sync);
  const frame = requestAnimationFrame(sync);
  return () => {
    cancelAnimationFrame(frame);
    observer.disconnect();
  };
}

export type OTPValidationType = "alpha" | "alphanumeric" | "none" | "numeric";

export function normalizeOTP(value: string, validationType: OTPValidationType): string {
  if (validationType === "none") return value;
  if (validationType === "numeric") return value.replace(/[^0-9]/g, "");
  if (validationType === "alpha") return value.replace(/[^A-Za-z]/g, "");
  return value.replace(/[^A-Za-z0-9]/g, "");
}

export function replaceOTPRange(
  current: string,
  insertion: string,
  index: number,
  length: number,
): string {
  const slots = Array.from({ length }, (_, slot) => current[slot] ?? "");
  for (const [offset, character] of Array.from(insertion).entries()) {
    if (index + offset >= length) break;
    slots[index + offset] = character;
  }
  return slots.join("");
}

export type { OTPFieldInputProps } from "./otp-field-input.svelte";
export { default as Input, default as OTPFieldInput } from "./otp-field-input.svelte";
export { normalizeOTP, type OTPValidationType, replaceOTPRange } from "./otp-field-machine.js";
export type { OTPFieldRootProps, OTPFieldSize } from "./otp-field-root.svelte";
export { default as OTPField, default as Root } from "./otp-field-root.svelte";
export type { OTPFieldSeparatorProps } from "./otp-field-separator.svelte";
export { default as OTPFieldSeparator, default as Separator } from "./otp-field-separator.svelte";
